import type {
  CreateMessageRequest,
  McpUiDownloadFileRequest,
  McpUiDownloadFileResult,
} from "@mcp-use/client/react";
import { useCallback } from "react";
import { toast } from "sonner";
import { RequestActionToast } from "@/client/components/shared/RequestActionToast";
import { useSamplingLLM } from "@/client/components/sampling/useSamplingLLM";
import type { LLMConfig } from "@/client/components/chat/types";

function filenameFromUri(uri: string): string {
  let candidate = uri;
  try {
    candidate = new URL(uri).pathname;
  } catch {
    // Non-HTTP MCP resource URIs are still valid filename sources.
  }
  const lastSegment = candidate.split("/").filter(Boolean).at(-1) ?? "download";
  let decodedSegment = lastSegment;
  try {
    decodedSegment = decodeURIComponent(lastSegment);
  } catch {
    // Keep the literal segment when it contains malformed percent escapes.
  }
  return (
    decodedSegment
      .replace(/[/\\?%*:|"<>]/g, "-")
      .replace(/^\.+/, "")
      .slice(0, 180) || "download"
  );
}

function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.rel = "noopener";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

async function downloadContents(
  contents: McpUiDownloadFileRequest["params"]["contents"]
): Promise<void> {
  for (const item of contents) {
    if (item.type === "resource") {
      const resource = item.resource;
      const mimeType = resource.mimeType ?? "application/octet-stream";
      const blob =
        "blob" in resource
          ? new Blob(
              [
                Uint8Array.from(atob(resource.blob), (char) =>
                  char.charCodeAt(0)
                ),
              ],
              { type: mimeType }
            )
          : new Blob([resource.text], { type: mimeType });
      downloadBlob(blob, filenameFromUri(resource.uri));
      continue;
    }

    const response = await fetch(item.uri);
    if (!response.ok) {
      throw new Error(`Download failed with HTTP ${response.status}`);
    }
    downloadBlob(await response.blob(), filenameFromUri(item.uri));
  }
}

export function useMcpAppsHostActions(llmConfig: LLMConfig | null | undefined) {
  const { generateResponse, isAvailable } = useSamplingLLM({
    llmConfig: llmConfig ?? null,
  });

  const onSamplingRequest = useCallback(
    (params: CreateMessageRequest["params"]) =>
      new Promise<Awaited<ReturnType<typeof generateResponse>>>(
        (resolve, reject) => {
          const toastId = toast(
            <RequestActionToast
              title="MCP App sampling request"
              description="This app wants to generate a model response."
              actions={[
                {
                  label: "Approve",
                  testId: "mcp-app-sampling-approve",
                  onClick: () => {
                    toast.dismiss(toastId);
                    void generateResponse({
                      request: { method: "sampling/createMessage", params },
                    }).then(resolve, reject);
                  },
                },
                {
                  label: "Deny",
                  testId: "mcp-app-sampling-deny",
                  onClick: () => {
                    toast.dismiss(toastId);
                    reject(new Error("User denied the sampling request"));
                  },
                },
              ]}
            />,
            { duration: Infinity }
          );
        }
      ),
    [generateResponse]
  );

  const onDownloadFile = useCallback(
    (params: McpUiDownloadFileRequest["params"]) =>
      new Promise<McpUiDownloadFileResult>((resolve, reject) => {
        const toastId = toast(
          <RequestActionToast
            title="MCP App download request"
            description={`Download ${params.contents.length} file${params.contents.length === 1 ? "" : "s"}?`}
            actions={[
              {
                label: "Download",
                testId: "mcp-app-download-confirm",
                onClick: () => {
                  toast.dismiss(toastId);
                  void downloadContents(params.contents)
                    .then(() => resolve({}))
                    .catch(reject);
                },
              },
              {
                label: "Deny",
                testId: "mcp-app-download-deny",
                onClick: () => {
                  toast.dismiss(toastId);
                  reject(new Error("User denied the download request"));
                },
              },
            ]}
          />,
          { duration: Infinity }
        );
      }),
    []
  );

  return {
    onSamplingRequest: isAvailable ? onSamplingRequest : undefined,
    onDownloadFile,
  };
}

import { Hono } from "hono";
import { afterEach, describe, expect, it, vi } from "vitest";
import { mountMcpProxy } from "../../src/server/proxy/mcp-proxy";

const proxyUrl = "http://localhost/inspector/api/proxy";

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("Inspector MCP proxy request isolation", () => {
  it("prefixes proxy logs only when sharing the dev server process", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn<typeof fetch>(async () => new Response("ok"))
    );
    const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
    const request = () =>
      new Request(proxyUrl, {
        headers: { "X-Target-URL": "https://93.184.216.34/mcp" },
      });

    const embedded = new Hono();
    mountMcpProxy(embedded, {
      path: "/inspector/api/proxy",
      logPrefix: "[inspector]",
    });
    await embedded.fetch(request());
    expect(logSpy.mock.calls).not.toHaveLength(0);
    expect(
      logSpy.mock.calls.every(([line]) =>
        String(line).startsWith("[inspector]")
      )
    ).toBe(true);

    logSpy.mockClear();
    const standalone = new Hono();
    mountMcpProxy(standalone, { path: "/inspector/api/proxy" });
    await standalone.fetch(request());
    expect(logSpy.mock.calls).not.toHaveLength(0);
    expect(
      logSpy.mock.calls.every(
        ([line]) => !String(line).startsWith("[inspector]")
      )
    ).toBe(true);
    logSpy.mockRestore();
  });

  it("does not forward Inspector cookies or browser-origin headers", async () => {
    const fetchFn = vi.fn<typeof fetch>(async (_input, init) => {
      const headers = new Headers(init?.headers);
      expect(headers.get("authorization")).toBe("Bearer mcp-token");
      expect(headers.get("cookie")).toBeNull();
      expect(headers.get("origin")).toBeNull();
      expect(headers.get("referer")).toBeNull();
      expect(headers.get("sec-fetch-site")).toBeNull();
      return new Response("ok", {
        headers: { "Set-Cookie": "upstream=must-not-reach-browser" },
      });
    });
    vi.stubGlobal("fetch", fetchFn);
    const app = new Hono();
    mountMcpProxy(app, {
      path: "/inspector/api/proxy",
      enableLogging: false,
    });

    const response = await app.fetch(
      new Request(proxyUrl, {
        method: "POST",
        headers: {
          Authorization: "Bearer mcp-token",
          Cookie: "inspector_session=must-not-leak",
          Origin: "http://localhost",
          Referer: "http://localhost/inspector",
          "Sec-Fetch-Site": "same-origin",
          "Content-Type": "application/json",
          "X-Target-URL": "https://93.184.216.34/mcp",
        },
        body: "{}",
      })
    );

    expect(response.status).toBe(200);
    expect(response.headers.get("set-cookie")).toBeNull();
    expect(fetchFn).toHaveBeenCalledOnce();
  });

  it("removes bearer authorization across a cross-origin redirect", async () => {
    const fetchFn = vi
      .fn<typeof fetch>()
      .mockImplementationOnce(async (_input, init) => {
        expect(new Headers(init?.headers).get("authorization")).toBe(
          "Bearer must-not-leak"
        );
        return new Response(null, {
          status: 307,
          headers: { Location: "https://93.184.216.35/mcp" },
        });
      })
      .mockImplementationOnce(async (_input, init) => {
        expect(new Headers(init?.headers).get("authorization")).toBeNull();
        return new Response("ok");
      });
    vi.stubGlobal("fetch", fetchFn);
    const app = new Hono();
    mountMcpProxy(app, {
      path: "/inspector/api/proxy",
      enableLogging: false,
    });

    const response = await app.fetch(
      new Request(proxyUrl, {
        method: "POST",
        headers: {
          Authorization: "Bearer must-not-leak",
          "Content-Type": "application/json",
          "X-Target-URL": "https://93.184.216.34/mcp",
        },
        body: "{}",
      })
    );

    expect(response.status).toBe(200);
    expect(fetchFn).toHaveBeenCalledTimes(2);
  });

  it("forwards an empty 204 response without constructing an invalid body", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn<typeof fetch>(async () => new Response(null, { status: 204 }))
    );
    const app = new Hono();
    mountMcpProxy(app, {
      path: "/inspector/api/proxy",
      enableLogging: false,
    });

    const response = await app.fetch(
      new Request(proxyUrl, {
        headers: {
          "X-Target-URL": "https://93.184.216.34/mcp",
        },
      })
    );

    expect(response.status).toBe(204);
    expect(await response.text()).toBe("");
  });

  it("disables reverse-proxy buffering for open-ended SSE responses", async () => {
    const stream = new ReadableStream({
      start(controller) {
        controller.enqueue(new TextEncoder().encode("data: ready\n\n"));
      },
    });
    vi.stubGlobal(
      "fetch",
      vi.fn<typeof fetch>(
        async () =>
          new Response(stream, {
            headers: { "Content-Type": "text/event-stream" },
          })
      )
    );
    const app = new Hono();
    mountMcpProxy(app, {
      path: "/inspector/api/proxy",
      enableLogging: false,
    });

    const response = await app.fetch(
      new Request(proxyUrl, {
        headers: {
          "X-Target-URL": "https://93.184.216.34/mcp",
        },
      })
    );

    expect(response.status).toBe(200);
    expect(response.headers.get("content-type")).toBe("text/event-stream");
    expect(response.headers.get("cache-control")).toBe(
      "no-cache, no-transform"
    );
    expect(response.headers.get("x-accel-buffering")).toBe("no");
  });

  it("preserves upstream cache policy while disabling SSE buffering", async () => {
    const stream = new ReadableStream({
      start(controller) {
        controller.enqueue(new TextEncoder().encode("data: ready\n\n"));
      },
    });
    vi.stubGlobal(
      "fetch",
      vi.fn<typeof fetch>(
        async () =>
          new Response(stream, {
            headers: {
              "Cache-Control": "private, no-store",
              "Content-Type": "text/event-stream",
            },
          })
      )
    );
    const app = new Hono();
    mountMcpProxy(app, {
      path: "/inspector/api/proxy",
      enableLogging: false,
    });

    const response = await app.fetch(
      new Request(proxyUrl, {
        headers: {
          "X-Target-URL": "https://93.184.216.34/mcp",
        },
      })
    );

    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("private, no-store");
    expect(response.headers.get("x-accel-buffering")).toBe("no");
  });
});

