# Observability Module

This module provides comprehensive observability for MCP agents using LangChain, supporting Langfuse observability platform.

## Features

- **Langfuse integration**: Comprehensive observability with Langfuse
- **Automatic instrumentation**: Zero-code observability with environment variables
- **Custom callbacks**: Support for custom LangChain callback handlers
- **TypeScript-first**: Full TypeScript support with proper types
- **Serverless-ready**: Proper shutdown handling for serverless environments

## Installation

Install the required packages based on your observability platform:

```bash
# For Langfuse
npm install langfuse langfuse-langchain
```

## Configuration

### Langfuse

Set the following environment variables:

```env
LANGFUSE_PUBLIC_KEY=pk-lf-...
LANGFUSE_SECRET_KEY=sk-lf-...
LANGFUSE_HOST=https://cloud.langfuse.com  # Optional
MCP_USE_LANGFUSE=true  # Set to false to disable
```

## Usage

### Basic Usage with MCPAgent

The observability is automatically integrated into MCPAgent:

```typescript
import { MCPAgent } from "@mcp-use/agent/langchain";

const agent = new MCPAgent({
  llm: myLLM,
  client: myMCPClient,
  // Observability is automatically enabled if environment variables are set
});

// Initialize the agent
await agent.initialize();

// Run queries - they will be automatically traced
const result = await agent.run("What's the weather?");
```

### Custom Callbacks

You can provide custom callbacks:

```typescript
import { CallbackHandler } from "langfuse-langchain";
import { MCPAgent } from "@mcp-use/agent/langchain";

const customHandler = new CallbackHandler({
  secretKey: "custom-secret",
  publicKey: "custom-public",
});

const agent = new MCPAgent({
  llm: myLLM,
  client: myMCPClient,
  callbacks: [customHandler], // Use custom callbacks instead of auto-detected ones
});
```

### Direct ObservabilityManager Usage

For advanced use cases, you can use the ObservabilityManager directly:

```typescript
import { ObservabilityManager } from "@mcp-use/agent/langchain";

// Create a manager
const manager = new ObservabilityManager({
  verbose: true, // Enable verbose logging
});

// Get available callbacks
const callbacks = await manager.getCallbacks();

// Check available handlers
const handlerNames = await manager.getHandlerNames();
console.log("Available handlers:", handlerNames);

// Add custom callback
manager.addCallback(myCustomCallback);

// Shutdown (important for serverless)
await manager.shutdown();
```

## Platform Features

### Langfuse Features

- Detailed LLM call tracing
- Chain execution tracking
- Tool usage monitoring
- Cost tracking
- Custom metadata and tags
- Session management
- User tracking

## Serverless Considerations

For serverless environments (AWS Lambda, Vercel, etc.), ensure proper shutdown:

```typescript
const agent = new MCPAgent({
  /* ... */
});

try {
  await agent.initialize();
  const result = await agent.run(query);
  return result;
} finally {
  // Important: Ensure traces are flushed
  await agent.close();
}
```

## Debugging

Enable debug logging to see observability events:

```typescript
import { logger } from "@mcp-use/client";

// Set log level to debug
process.env.LOG_LEVEL = "debug";

// Now you'll see detailed observability logs
```

## Environment Variables Reference

### Langfuse

- `LANGFUSE_PUBLIC_KEY` - Required: Your Langfuse public key
- `LANGFUSE_SECRET_KEY` - Required: Your Langfuse secret key
- `LANGFUSE_HOST` / `LANGFUSE_BASEURL` - Optional: Langfuse API URL (default: https://cloud.langfuse.com)
- `LANGFUSE_RELEASE` - Optional: Release/version identifier
- `LANGFUSE_FLUSH_AT` - Optional: Batch size for flushing (default: 15)
- `LANGFUSE_FLUSH_INTERVAL` - Optional: Flush interval in ms (default: 10000)
- `LANGFUSE_REQUEST_TIMEOUT` - Optional: Request timeout in ms (default: 10000)
- `LANGFUSE_ENABLED` - Optional: Set to "false" to disable
- `MCP_USE_LANGFUSE` - Optional: Set to "false" to disable Langfuse integration

## Examples

See the [examples](../../examples/) directory for complete working examples:

- Basic observability setup
- Multi-platform configuration
- Custom callback handlers
- Serverless deployments

/**
 * Unit tests for FileKVStore.
 *
 * Run with:
 *   pnpm --filter @mcp-use/client test:run -- tests/unit/auth/storage.test.ts
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { FileKVStore } from "../../../src/auth/storage-file.js";
import {
  existsSync,
  mkdtempSync,
  readdirSync,
  rmSync,
  statSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const isWindows = process.platform === "win32";

let baseDir: string;

beforeEach(() => {
  baseDir = mkdtempSync(join(tmpdir(), "mcp-use-fkv-"));
});

afterEach(() => {
  rmSync(baseDir, { recursive: true, force: true });
});

describe("FileKVStore", () => {
  it("does not create its directory until the first write", () => {
    const dir = join(baseDir, "abc123");
    const kv = new FileKVStore("abc123", baseDir);

    expect(existsSync(dir)).toBe(false);
    expect(kv.get("missing")).toBeNull();
    expect(kv.keys()).toEqual([]);
    expect(() => kv.remove("missing")).not.toThrow();
    expect(existsSync(dir)).toBe(false);

    kv.set("tokens", "secret");

    expect(existsSync(dir)).toBe(true);
  });

  it("round-trips simple keys", () => {
    const kv = new FileKVStore("abc123", baseDir);
    kv.set("tokens", '{"access":"x"}');
    expect(kv.get("tokens")).toBe('{"access":"x"}');
  });

  it("returns null for missing keys", () => {
    const kv = new FileKVStore("abc123", baseDir);
    expect(kv.get("nope")).toBeNull();
  });

  it("removes keys", () => {
    const kv = new FileKVStore("abc123", baseDir);
    kv.set("k", "v");
    expect(kv.get("k")).toBe("v");
    kv.remove("k");
    expect(kv.get("k")).toBeNull();
  });

  it("remove on missing key is a no-op", () => {
    const kv = new FileKVStore("abc123", baseDir);
    expect(() => kv.remove("never-set")).not.toThrow();
  });

  it("lists keys (excluding tmp files)", () => {
    const kv = new FileKVStore("abc123", baseDir);
    kv.set("tokens", "1");
    kv.set("client_info", "2");
    expect(kv.keys().sort()).toEqual(["client_info", "tokens"]);
  });

  it("isolates per server hash", () => {
    const a = new FileKVStore("hash-a", baseDir);
    const b = new FileKVStore("hash-b", baseDir);
    a.set("tokens", "from-a");
    b.set("tokens", "from-b");
    expect(a.get("tokens")).toBe("from-a");
    expect(b.get("tokens")).toBe("from-b");
  });

  it("sanitizes keys with colons (cross-platform safety)", () => {
    const kv = new FileKVStore("abc123", baseDir);
    kv.set("mcp:auth_abc123_tokens", "T");
    kv.set("mcp:auth:state_xyz", "S");
    expect(kv.get("mcp:auth_abc123_tokens")).toBe("T");
    expect(kv.get("mcp:auth:state_xyz")).toBe("S");
    // Keys list returns sanitized filenames, both present.
    expect(kv.keys()).toHaveLength(2);
  });

  it("rejects directory traversal in keys", () => {
    const kv = new FileKVStore("abc123", baseDir);
    // Sanitization replaces "/" with "_", so this becomes a flat name.
    expect(() => kv.set("../escape", "no")).not.toThrow();
    expect(kv.get("../escape")).toBe("no");
    // The actual file should be inside this.dir, not outside it.
    const files = readdirSync(baseDir);
    // baseDir contains exactly one subdir (abc123); no traversal-up files.
    expect(files).toEqual(["abc123"]);
  });

  it("overwrites existing values atomically (no .tmp residue)", () => {
    const kv = new FileKVStore("abc123", baseDir);
    kv.set("k", "v1");
    kv.set("k", "v2");
    expect(kv.get("k")).toBe("v2");
    // No temp files left over.
    const dir = join(baseDir, "abc123");
    const remaining = readdirSync(dir);
    expect(remaining.filter((n) => n.includes(".tmp."))).toEqual([]);
  });

  it.skipIf(isWindows)("creates dir 0o700 and files 0o600", () => {
    const kv = new FileKVStore("abc123", baseDir);
    kv.set("tokens", "secret");
    const dirStat = statSync(join(baseDir, "abc123"));
    expect(dirStat.mode & 0o777).toBe(0o700);
    const fileStat = statSync(join(baseDir, "abc123", "tokens"));
    expect(fileStat.mode & 0o777).toBe(0o600);
  });
});
